export declare const catsBody = "\n    <div class=\"cat-card\">\n        <h1>Meet Coco and Louis</h1>\n        <p>\n            These fluffballs are my two year old cats. They're from the same litter of Balinese cats which we chose because of their hypoallergenic\n            properties (my dad and brother are allergic to most cats). They're spoiled and act like they run the place.\n        </p>\n        <img src=\"/public/cat-images/bothCats.png\" alt=\"both cats img\" class=\"cat-photo\"/>\n    </div>\n\n    <div class=\"cat-card\">\n        <h2>Coco</h2>\n        <p>\n            The smaller of the two, Coco is very affectionate and constantly begs for treats. She loves to bask in sunlight during the day and she chases small toys around the house by night. Louis often chases her but when he sits on her bed, she doesn't hesitate to bully him out.\n        </p>\n        <div class=\"carousel-container\">\n            <div class=\"carousel-slide\">\n                <img src=\"/public/cat-images/coco1.png\" alt=\"coco img 1\" class=\"active\">\n                <img src=\"/public/cat-images/coco2.png\" alt=\"coco img 2\">\n                <img src=\"/public/cat-images/coco3.png\" alt=\"coco img 3\">\n            </div>\n            <button class=\"prev-btn\">&#10094;</button>\n            <button class=\"next-btn\">&#10095;</button>\n        </div>\n    </div>\n\n    <div class=\"cat-card\">\n        <h2>Louis</h2>\n        <p>\n            Named after Louis Armstrong for his raspy voice, Louis is a lazy brick. Despite his beautiful looks, he often spends his days staring at walls and looking confused. It often seems like no thoughts occur behind his large eyes. He loves scratches around the neck and back, but clipping his claws is a nightmare!\n        </p>\n        <div class=\"carousel-container\">\n            <div class=\"carousel-slide\">\n                <img src=\"/public/cat-images/louis1.png\" alt=\"louis img 1\" class=\"active\">\n                <img src=\"/public/cat-images/louis2.png\" alt=\"louis img 2\">\n                <img src=\"/public/cat-images/louis3.png\" alt=\"louis img 3\">\n            </div>\n            <button class=\"prev-btn\">&#10094;</button>\n            <button class=\"next-btn\">&#10095;</button>\n        </div>\n\n    </div>\n\n";
